// EaseMate signing bridge: the upstream API requires a signature generated by
// its wasm-bindgen module, so the Go backend delegates this provider to Node.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const bridgeDir = path.dirname(fileURLToPath(import.meta.url));
const localModule = path.join(bridgeDir, 'easemate-web.js');
const repoModule = path.resolve(bridgeDir, '..', '..', 'lib', 'easemate-web.js');
const modulePath = fs.existsSync(localModule) ? localModule : repoModule;

if (!fs.existsSync(modulePath)) {
  console.error('EaseMate bridge module not found');
  process.exit(1);
}

// Keep stdout reserved for the JSON result; the provider logs progress via console.log.
console.log = (...args) => console.error(...args);

const chunks = [];
for await (const chunk of process.stdin) {
  chunks.push(chunk);
}
const prompt = Buffer.concat(chunks).toString('utf8');

try {
  const { generateEasemate } = await import(pathToFileURL(modulePath).href);
  const result = await generateEasemate({ prompt });
  process.stdout.write(JSON.stringify(result));
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
}
